    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apositions\u3001healths\u3001directions\u3002",
    "\u8f93\u51fa list<integer> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def survivedRobotsHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:\n        n = len(positions)\n        idx = list(range(n))\n        idx.sort(key=lambda i: positions[i])\n\n        alive = []\n        for i in idx:\n            curIdx, curHp, curDir = i, healths[i], directions[i]\n            while alive:\n                prevIdx, prevHp, prevDir = alive[-1]\n                if prevDir == \"R\" and curDir == \"L\":\n                    alive.pop()\n                    if prevHp > curHp:\n                        curIdx, curHp, curDir = prevIdx, prevHp - 1, prevDir\n                    elif prevHp < curHp:\n                        curHp -= 1\n                    else:\n                        curIdx = -1\n                        break\n                else:\n                    break\n            if curIdx != -1:\n                alive.append((curIdx, curHp, curDir))\n\n        alive.sort(key=lambda o: o[0])\n        return list(o[1] for o in alive)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.survivedRobotsHealths(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
