    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def isValid(self, code: str) -> bool:\n        n = len(code)\n        tags = list()\n\n        i = 0\n        while i < n:\n            if code[i] == \"<\":\n                if i == n - 1:\n                    return False\n                if code[i + 1] == \"/\":\n                    j = code.find(\">\", i)\n                    if j == -1:\n                        return False\n                    tagname = code[i+2:j]\n                    if not tags or tags[-1] != tagname:\n                        return False\n                    tags.pop()\n                    i = j + 1\n                    if not tags and i != n:\n                        return False\n                elif code[i + 1] == \"!\":\n                    if not tags:\n                        return False\n                    cdata = code[i+2:i+9]\n                    if cdata != \"[CDATA[\":\n                        return False\n                    j = code.find(\"]]>\", i)\n                    if j == -1:\n                        return False\n                    i = j + 3\n                else:\n                    j = code.find(\">\", i)\n                    if j == -1:\n                        return False\n                    tagname = code[i+1:j]\n                    if not 1 <= len(tagname) <= 9 or not all(ch.isupper() for ch in tagname):\n                        return False\n                    tags.append(tagname)\n                    i = j + 1\n            else:\n                if not tags:\n                    return False\n                i += 1\n        \n        return not tags\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.isValid(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
