    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1anums\u3001k\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nMAX = 1_00_000\nprimes = [0] * (MAX + 1)\n\nfor i in range(2, MAX + 1):\n    if primes[i] > 0: continue\n    for j in range(i, MAX + 1, i): primes[j] += 1\n\nclass Solution:\n    def maximumScore(self, nums: List[int], k: int) -> int:\n        if k == 0: return 0\n        \n        n = len(nums)\n\n        left, right = [0] * n, [0] * n\n        stack = [(-1, 1_000_000_007)]\n        \n        for i,num in enumerate(nums):\n            while stack[-1][1] < primes[num]:\n                lastIdx, lastPrime = stack[-1]\n                right[lastIdx] = i - lastIdx\n                stack.pop()\n            right[stack[-1][0]] = i - stack[-1][0]\n            left[i] = i - stack[-1][0]\n            stack.append((i, primes[num]))\n            \n        \n        while stack[-1][1] < 1_000_000_007:\n            lastIdx, lastPrime = stack[-1]\n            right[lastIdx] = n - lastIdx\n            stack.pop()\n            \n        ans = 1\n\n        numsSort = sorted(list(enumerate(nums)), key=lambda it:-it[1])\n        for i,num in numsSort:\n            count = left[i] * right[i]\n            # print(num, count)\n\n            # \u76f4\u5199\u5e42\uff0c\u8d85\u65f6\n            # ans *= num ** min(count, k)\n            # ans %= 1_000_000_007\n\n            # \u679a\u4e3e\u5e42\uff0c\u8d85\u65f6\n            # for _ in range(min(count, k)):\n            #     ans *= num\n            #     ans %= 1_000_000_007\n\n            # \u624b\u5199\u5feb\u901f\u5e42\n            ans = self.pow(num, min(count, k), ans)\n\n            if count >= k: break\n            k -= count\n        \n        return ans\n\n    def pow(self, num: int, powNum: int, base: int) -> int:\n        while powNum:\n            if powNum & 1 == 1: base = base * num % 1_000_000_007\n            num = num * num % 1_000_000_007\n            powNum >>= 1\n        return base\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maximumScore(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
